import{z as i,x as A,o as E,c as p,q as l,j as n,D as e,d as t,s as B,S as s,b as r}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"到限价簿：理论在此停","description":"","frontmatter":{"title":"到限价簿：理论在此停","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/to-limit-order-book.md","filePath":"econ/to-limit-order-book.md","lastUpdated":1791063341000}'),d={name:"econ/to-limit-order-book.md"};function u(m,a,D,c,h,f){const o=A("Mermaid");return E(),p("div",null,[a[2]||(a[2]=l('<h1 id="到限价簿-理论在此停" tabindex="-1">到限价簿：理论在此停 <a class="header-anchor" href="#到限价簿-理论在此停" aria-label="Permalink to &quot;到限价簿：理论在此停&quot;">​</a></h1><div class="epigraph"><p>均衡给出价格应当满足的等式；限价簿是价格被生产出来的协议。理论在等式处停，协议从队列处起。</p><footer>—— 本栏收束；簿的几何见 Harris, Trading and Exchanges</footer></div><p><a href="/econ/affine-yield-curve">上一课</a>（仿射期限结构）。仿射因子已经补在栖息地之后。从偏好走到 SDF、CAPM 与期限结构，本栏已经有一套关于<strong>哪一个数字可以叫价格</strong>的理论。本课是主干最后一课：缺口不是再写一个均衡模型，而是承认这些数字还没有交易程序。程序在量化栏的<a href="/quant/lob-structure">限价簿结构</a>。后课不在本栏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>瓦尔拉斯拍卖人、Arrow–Debreu 证券、CAPM 的市场组合、EH 的收益率，都假定存在一个使供需相等的 \\(p\\)，交易在 \\(p\\) 上瞬时完成。没有人问：\\(p\\) 如何出现在屏幕上、谁有权在某个价位排队、不成交的意愿如何被记录。若继续在本栏写「市场微观结构」，会把金融理论吞进撮合引擎，也会把量化栏的第一课变成重复。</p><p>缺口因此是交接。本栏的对象是配置、合同与均衡关系：偏好、生产、一般均衡、货币与银行、资本结构、\\(p=E[mx]\\)。量化栏的对象是协议：限价单、市价单、时间优先、价差。两者在「有一个可交易价格」处相切，不相吞。本课把切点写清楚，然后停笔。</p><p><span class="marginnote">Walrasian \\(p\\) 是清值。LOB 上的中间价是最佳买卖价的中点，不是清值，甚至不是任何人必须成交的价。把中点叫成均衡价格，是后文 Glosten–Milgrom 与 Roll 要拆的习惯，不是本栏的定理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把本栏用过的「价格」收成三类，都<strong>不是</strong>簿。第一，一般均衡价格：商品与或有要求权的 \\(p\\)，使超额需求为零。第二，资产定价核：\\(p=E[mx]\\)，CAPM 与 EH 是它的特化。第三，公司金融里的市价：MM 套利、发行柠檬、股利公告所引用的那个 \\(p\\)，EMH 说它反映 \\(\\Phi\\)。三类都是均衡或信息条件，没有状态机。</p><p>限价簿是状态机。未成交的买卖意愿按价格分层、按时间（或比例规则）排队；交叉时撮合，未交叉时停在簿上。Harris 称之为连续双向拍卖。它回答的问题是协议问题：立刻成交的价是什么、下一档还有多少、新单插在哪。这些问题在 <a href="/quant/lob-structure">LOB 结构</a> 的第一课从零铺垫；本栏读者到那里时，只携带「理论上应当有一个 \\(p\\)」，不携带簿的几何。</p><p><span class="marginnote">「连续双向拍卖」就是买卖两边同时挂单、订单随到随撮合的机制——与传统拍卖只有一个卖家等买家竞价不同，这里价格由两边的队列共同决定，买方也在报价。</span></p><p><span class="marginnote">「状态机」就是只按当前状态和新到事件决定下一步的机器。簿不需要记住「为什么」，只需要记住每一档挂着多少、谁先谁后；新单一到，按规则走下一格。给个数字实例：你在 10.00 元挂买单排第一，之后来一张 10.00 元的卖单就先与你成交；若卖单挂在 10.05 元，双方都在簿上等待，中间五分钱的空档就是价差的一部分。</span></p>',12)),(E(),n(s,null,{default:e(()=>[B(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PREF%5B%22%E5%81%8F%E5%A5%BD%E4%B8%8E%E4%B8%80%E8%88%AC%E5%9D%87%E8%A1%A1%22%5D%20--%3E%20P%5B%22%E5%9D%87%E8%A1%A1%E4%BB%B7%E6%A0%BC%20p%22%5D%0A%20%20SDF%5B%22SDF%20%2F%20CAPM%20%2F%20EH%22%5D%20--%3E%20P%0A%20%20CORP%5B%22MM%20%E4%B8%8E%20EMH%20%E7%9A%84%E5%B8%82%E4%BB%B7%22%5D%20--%3E%20P%0A%20%20P%20--%3E%20STOP%5B%22%E6%9C%AC%E6%A0%8F%E4%B8%BB%E5%B9%B2%E5%81%9C%22%5D%0A%20%20STOP%20--%3E%20LOB%5B%22%E9%99%90%E4%BB%B7%E7%B0%BF%3A%20%E5%8D%8F%E8%AE%AE%E4%B8%8E%E9%98%9F%E5%88%97%22%5D%0A%20%20LOB%20--%3E%20QUANT%5B%22%2Fquant%2Flob-structure%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("p",null,"交接句必须硬：理论停；簿是协议。不要把 CAPM 的 \\(R_m\\) 当成盘口中间价的时间平均，也不要把 EH 的 \\(y^{(n)}\\) 当成国债的某一档挂单价。那些映射需要微观结构与久期约定，是量化栏的工作。",-1)),a[4]||(a[4]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=r("p",null,"为什么均衡语言不够用？因为出清是对配置的描述，不是对消息与队列的描述。真实市场在时间上展开：买单到达、排队、被撤、被扫。价格形成是这个过程的产物，O'Hara 强调过这一点。过程会制造价差、深度空洞、短暂的交叉，这些对象在 \\(p=E[mx]\\) 里没有符号。若强行在本栏引入做市商，会与已经写完的银行中介、与尚未写的 LOB 抢定义。",-1)),a[6]||(a[6]=r("p",null,"因此机制课在此是负面的：不再增加一条均衡定理。正向的机制从量化栏开始——价格优先如何把「更优的价」变成可验证的排序。本栏读者若跳过交接直接读因子实证，会把测量误差当成定价核的失败；先读簿，才知道收益是什么事件的记录。",-1)),(E(),n(s,null,{default:e(()=>[B(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ARR%5B%22%E6%96%B0%E8%AE%A2%E5%8D%95%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20TYPE%7B%22%E5%B8%82%E4%BB%B7%E5%8D%95%E8%BF%98%E6%98%AF%E9%99%90%E4%BB%B7%E5%8D%95%22%7D%0A%20%20TYPE%20--%3E%7C%22%E5%B8%82%E4%BB%B7%22%7C%20HIT%5B%22%E7%AB%8B%E5%8D%B3%E5%90%83%E6%8E%89%E5%AF%B9%E6%89%8B%E6%96%B9%E5%90%91%E9%98%9F%E5%88%97%22%5D%0A%20%20TYPE%20--%3E%7C%22%E9%99%90%E4%BB%B7%22%7C%20JOIN%5B%22%E6%8C%89%E4%BB%B7%E6%A0%BC%E5%88%86%E5%B1%82%E5%85%A5%E7%B0%BF%E6%8E%92%E9%98%9F%22%5D%0A%20%20JOIN%20--%3E%20WAIT%5B%22%E7%AD%89%E5%BE%85%E6%88%90%E4%BA%A4%E6%88%96%E6%92%A4%E9%94%80%22%5D%0A%20%20WAIT%20--%3E%20FORM%5B%22%E6%88%90%E4%BA%A4%E4%BB%B7%E6%98%AF%E8%BF%87%E7%A8%8B%E7%9A%84%E4%BA%A7%E7%89%A9%22%5D%0A%20%20HIT%20--%3E%20FORM%0A%20%20FORM%20--%3E%20OBJ%5B%22%E4%BB%B7%E5%B7%AE%20%2F%20%E6%B7%B1%E5%BA%A6%E7%A9%BA%E6%B4%9E%20%2F%20%E7%9F%AD%E6%9A%82%E4%BA%A4%E5%8F%89%22%5D%0A%20%20OBJ%20--%3E%20EQ%5B%22%E5%9D%87%E8%A1%A1%E7%AD%89%E5%BC%8F%E5%8F%AA%E7%BA%A6%E6%9D%9F%E7%BB%93%E6%9E%9C%2C%20%E4%B8%8D%E6%8F%8F%E8%BF%B0%E9%98%9F%E5%88%97%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">常见误区：初学者容易以为均衡价格和屏幕上的成交价是一回事。实际上，Walrasian 出清价是让超额需求为零的理论值，成交价却取决于买方队列被扫到了哪一档——后者是撮合协议给出的，两者可以长期不一致。</span></p><h3 id="理论停-簿是协议" tabindex="-1">理论停；簿是协议 <a class="header-anchor" href="#理论停-簿是协议" aria-label="Permalink to &quot;理论停；簿是协议&quot;">​</a></h3><p>这句话要按字面执行。本栏不再写做市商存货、知情交易或买卖价差分解——那些会与银行中介抢「中介」一词，也会把量化栏第一课掏空。Harris 的连续双向拍卖、价格优先加时间优先、tick 网格，全部从 <a href="/quant/lob-structure">/quant/lob-structure</a> 起笔，并声明后课已经默认读过本栏主干。CAPM 的 \\(R_m\\) 不是盘口中点的平均；EH 的 \\(y^{(n)}\\) 不是某一档挂单价。映射需要约定与微观结构，是换栏之后的工作。</p><p><span class="marginnote">O&#39;Hara：价格形成是交易过程的产物。过程的状态机是簿；均衡等式是对过程结果的限制，不是过程本身。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是微观结构综述。Glosten–Milgrom、Kyle、Roll 价差分解全部在量化栏，按课程序列出现。本栏也不回头改写 CAPM：均衡陈述仍在<a href="/econ/capm-theory">前一课序</a>，实证仍在<a href="/quant/capm">/quant/capm</a>。附录论文课（Arrow–Debreu、Akerlof、Keynes、Woodford、Diamond–Dybvig 原文等）是对照，不插入主干，不接在本课之后当成第十五课。</p><p>栏与栏互不吞并在此落地：金融接到限价簿为止；量化从限价簿起笔。打开 <a href="/quant/lob-structure">/quant/lob-structure</a> 时，默认已经读完本栏主干到这一句。</p><p>附录十篇（Arrow–Debreu、Debreu 书、Akerlof、Spence、Rothschild–Stiglitz、Keynes、Friedman、Kydland–Prescott、Woodford、Diamond–Dybvig 原文）是对照，阅读顺序在附录课程内，不充当主干第十五课。读完本课若继续，应打开量化栏，而不是打开第一篇附录当作「下一课」。</p><p>理论停。簿是协议。Walrasian \\(p\\) 不是盘口中点。</p><p>Glosten–Milgrom、Kyle、Roll 分解按量化栏课序出现，本课不预支。</p><p>打开 <a href="/quant/lob-structure">/quant/lob-structure</a> 时，只携带「应当有一个均衡价格」，不携带队列几何。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本栏给出均衡与合同意义上的价格；不给出交易协议。</li><li>限价簿是连续双向拍卖的状态机，不是 Walrasian \\(p\\) 的另一种写法。</li><li>主干在此结束。下一课是量化栏第一课：<a href="/quant/lob-structure">限价簿结构</a>。</li><li>附录对照另起，不插入本课之后。</li></ul>',13))])}const P=i(d,[["render",u]]);export{F as __pageData,P as default};
